<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_admin();$counts=[];foreach(["slots"=>"SELECT COUNT(*) c FROM slots", "active"=>"SELECT COUNT(*) c FROM bookings WHERE status IN ('paid','entered')", "revenue"=>"SELECT COALESCE(SUM(amount),0) c FROM payments WHERE status='paid'", "fines"=>"SELECT COALESCE(SUM(fine_amount),0) c FROM bookings"] as $k=>$q)$counts[$k]=$mysqli->query($q)->fetch_assoc()['c'];$recent=$mysqli->query('SELECT b.*,u.name,s.slot_number FROM bookings b JOIN users u ON u.id=b.user_id JOIN slots s ON s.id=b.slot_id ORDER BY b.id DESC LIMIT 8');$page_title='Admin dashboard';require __DIR__.'/../includes/header.php'; ?>
<h2>Administrator dashboard</h2><div class="row g-3 my-2"><?php foreach([['Total slots',$counts['slots'],'primary'],['Active bookings',$counts['active'],'success'],['Payment revenue','₹'.number_format($counts['revenue'],2),'dark'],['Fines assessed','₹'.number_format($counts['fines'],2),'warning']] as [$label,$value,$color]):?><div class="col-md-3"><div class="card stat-card shadow-sm p-3"><small class="text-muted"><?=$label?></small><strong class="h3 text-<?=$color?>"><?=$value?></strong></div></div><?php endforeach;?></div><p><a class="btn btn-primary btn-sm" href="slots.php">Manage slots</a> <a class="btn btn-outline-primary btn-sm" href="scan.php">Scan QR / Entry & Exit</a> <a class="btn btn-outline-primary btn-sm" href="reports.php">Reports</a></p><div class="card shadow-sm border-0"><div class="card-header bg-white"><b>Recent bookings</b></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Code</th><th>Owner</th><th>Slot</th><th>Status</th></tr></thead><tbody><?php while($b=$recent->fetch_assoc()):?><tr><td><?=e($b['booking_code'])?></td><td><?=e($b['name'])?></td><td><?=e($b['slot_number'])?></td><td><?=e($b['status'])?></td></tr><?php endwhile;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
